import { getStore } from "@netlify/blobs";

export default async (request, context) => {
    const headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        'Content-Type': 'application/json'
    };

    if (request.method !== 'DELETE') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405, headers });
    }

    // Verify authentication
    const authHeader = request.headers.get('Authorization');
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers });
    }

    const token = authHeader.split(' ')[1];
    let userId;

    try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        userId = payload.sub;
    } catch (e) {
        return new Response(JSON.stringify({ error: 'Invalid token' }), { status: 401, headers });
    }

    const url = new URL(request.url);
    const calendarId = url.searchParams.get('id');

    if (!calendarId) {
        return new Response(JSON.stringify({ error: 'Calendar ID is required' }), { status: 400, headers });
    }

    try {
        const calendarStore = getStore("calendars");
        const userStore = getStore("user-calendars");

        // Get calendar to verify ownership
        let calendar;
        try {
            calendar = await calendarStore.get(calendarId, { type: 'json' });
            if (!calendar) {
                return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
            }
        } catch (e) {
            return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
        }

        // Verify ownership
        if (calendar.ownerId !== userId) {
            return new Response(JSON.stringify({ error: 'Forbidden: You do not own this calendar' }), { status: 403, headers });
        }

        // Delete calendar
        await calendarStore.delete(calendarId);

        // Remove from user's calendar list
        try {
            let userCalendars = [];
            const existing = await userStore.get(userId, { type: 'json' });
            if (existing) {
                userCalendars = existing.filter(cal => cal.id !== calendarId);
                await userStore.setJSON(userId, userCalendars);
            }
        } catch (e) {}

        return new Response(JSON.stringify({ 
            success: true, 
            message: 'Calendar deleted' 
        }), { status: 200, headers });

    } catch (error) {
        console.error('Error deleting calendar:', error);
        return new Response(JSON.stringify({ error: 'Internal server error' }), { status: 500, headers });
    }
};

import { getStore } from "@netlify/blobs";

export default async (request, context) => {
    const headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        'Content-Type': 'application/json'
    };

    if (request.method !== 'GET') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405, headers });
    }

    // Get calendar ID from query parameter
    const url = new URL(request.url);
    const calendarId = url.searchParams.get('id');

    if (!calendarId) {
        return new Response(JSON.stringify({ error: 'Calendar ID is required' }), { status: 400, headers });
    }

    try {
        const calendarStore = getStore("calendars");

        try {
            const calendar = await calendarStore.get(calendarId, { type: 'json' });
            if (!calendar) {
                return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
            }

            // Return calendar data (without sensitive info if needed)
            return new Response(JSON.stringify(calendar), { status: 200, headers });
        } catch (e) {
            return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
        }
    } catch (error) {
        console.error('Error retrieving calendar:', error);
        return new Response(JSON.stringify({ error: 'Internal server error' }), { status: 500, headers });
    }
};

import { getStore } from "@netlify/blobs";

export default async (request, context) => {
    const headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        'Content-Type': 'application/json'
    };

    if (request.method !== 'GET') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405, headers });
    }

    const url = new URL(request.url);
    const calendarId = url.searchParams.get('calendarId');

    if (!calendarId) {
        return new Response(JSON.stringify({ error: 'Calendar ID is required' }), { status: 400, headers });
    }

    try {
        const calendarStore = getStore("calendars");

        try {
            const calendar = await calendarStore.get(calendarId, { type: 'json' });
            if (!calendar) {
                return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
            }

            // Return only unavailability data
            return new Response(JSON.stringify({ 
                unavailability: calendar.unavailability || {} 
            }), { status: 200, headers });
        } catch (e) {
            return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
        }
    } catch (error) {
        console.error('Error retrieving unavailability:', error);
        return new Response(JSON.stringify({ error: 'Internal server error' }), { status: 500, headers });
    }
};

import { getStore } from "@netlify/blobs";

export default async (request, context) => {
    const headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        'Content-Type': 'application/json'
    };

    if (request.method !== 'GET') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405, headers });
    }

    const url = new URL(request.url);
    const calendarId = url.searchParams.get('calendarId');
    const participantName = url.searchParams.get('participant');

    if (!calendarId) {
        return new Response(JSON.stringify({ error: 'Calendar ID is required' }), { status: 400, headers });
    }

    try {
        const calendarStore = getStore("calendars");

        try {
            const calendar = await calendarStore.get(calendarId, { type: 'json' });
            if (!calendar) {
                return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
            }

            let submissions;
            if (participantName) {
                // Get specific participant's submission
                submissions = calendar.unavailability?.[participantName] || null;
            } else {
                // Get all submissions
                submissions = calendar.unavailability || {};
            }

            return new Response(JSON.stringify({ submissions }), { status: 200, headers });
        } catch (e) {
            return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
        }
    } catch (error) {
        console.error('Error retrieving submissions:', error);
        return new Response(JSON.stringify({ error: 'Internal server error' }), { status: 500, headers });
    }
};

import { getStore } from "@netlify/blobs";

export default async (request, context) => {
    const headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        'Content-Type': 'application/json'
    };

    if (request.method !== 'POST') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405, headers });
    }

    const url = new URL(request.url);
    const calendarId = url.searchParams.get('calendarId');
    const participantName = url.searchParams.get('participant');

    if (!calendarId || !participantName) {
        return new Response(JSON.stringify({ error: 'Calendar ID and participant name are required' }), { status: 400, headers });
    }

    try {
        const calendarStore = getStore("calendars");

        // Get calendar
        let calendar;
        try {
            calendar = await calendarStore.get(calendarId, { type: 'json' });
            if (!calendar) {
                return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
            }
        } catch (e) {
            return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
        }

        // Initialize unavailability object if it doesn't exist
        if (!calendar.unavailability) {
            calendar.unavailability = {};
        }

        // Remove participant's unavailability
        delete calendar.unavailability[participantName];

        // Save updated calendar
        await calendarStore.setJSON(calendarId, calendar);

        return new Response(JSON.stringify({ 
            success: true, 
            message: 'Unavailability reset for participant',
            participant: participantName 
        }), { status: 200, headers });

    } catch (error) {
        console.error('Error resetting unavailability:', error);
        return new Response(JSON.stringify({ error: 'Internal server error' }), { status: 500, headers });
    }
};

import { getStore } from "@netlify/blobs";

export default async (request, context) => {
    const headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        'Content-Type': 'application/json'
    };

    if (request.method !== 'POST') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), { status: 405, headers });
    }

    const url = new URL(request.url);
    const calendarId = url.searchParams.get('calendarId');

    if (!calendarId) {
        return new Response(JSON.stringify({ error: 'Calendar ID is required' }), { status: 400, headers });
    }

    try {
        const body = await request.json();
        const { participantName, unavailableDates } = body;

        if (!participantName || !participantName.trim()) {
            return new Response(JSON.stringify({ error: 'Participant name is required' }), { status: 400, headers });
        }

        if (!Array.isArray(unavailableDates)) {
            return new Response(JSON.stringify({ error: 'Unavailable dates must be an array' }), { status: 400, headers });
        }

        const calendarStore = getStore("calendars");

        // Get calendar
        let calendar;
        try {
            calendar = await calendarStore.get(calendarId, { type: 'json' });
            if (!calendar) {
                return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
            }
        } catch (e) {
            return new Response(JSON.stringify({ error: 'Calendar not found' }), { status: 404, headers });
        }

        // Initialize unavailability object if it doesn't exist
        if (!calendar.unavailability) {
            calendar.unavailability = {};
        }

        // Store participant's unavailability
        calendar.unavailability[participantName] = {
            dates: unavailableDates,
            submittedAt: new Date().toISOString()
        };

        // Save updated calendar
        await calendarStore.setJSON(calendarId, calendar);

        return new Response(JSON.stringify({ 
            success: true, 
            message: 'Unavailability submitted',
            participant: participantName 
        }), { status: 200, headers });

    } catch (error) {
        console.error('Error submitting unavailability:', error);
        return new Response(JSON.stringify({ error: 'Internal server error' }), { status: 500, headers });
    }
};
